import {gradientDefinition} from './appearance.js';
import {fabricPattern} from './fabric.js';
import {orderedObjects} from './layers.js';
import {documentSpec,documentBackground} from './document.js';
import {visible} from './model.js';
import {pathD,evaluatedPath,worldPath,I} from './core.js';
import {effectParts,modifierParts} from './effects.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mat=m=>`matrix(${(m||I()).join(' ')})`;
export const partsSvg=parts=>parts.map(p=>`<path d="${p.d}" stroke="${esc(p.stroke)}" stroke-width="${p.width}" fill="${esc(p.fill)}" fill-rule="evenodd" stroke-linejoin="round" stroke-linecap="round"${p.dash?` stroke-dasharray="${p.dash}"`:''}${p.opacity!==undefined?` opacity="${p.opacity}"`:''}${p.ownerId?` data-owner="${esc(p.ownerId)}"`:''}${p.ownerModifier?` data-modifier-owner="${esc(p.ownerModifier)}"`:''}${p.role?` data-role="${p.role}"`:''}/>`).join('');
export function objectSvg(o,objects,hit=false){if(o.semanticType==='region'&&objects.find(p=>p.id===o.panelOf)?.regionIds?.length)return '';let visual='',m=o.matrix||I(),extra='',panels='',baseTexture='';let style=`stroke="${esc(o.stroke||'none')}" stroke-width="${o.width??0}" fill="${esc(o.gradient?'url(#gradient-'+o.id+')':o.fill||(o.type==='text'?'#222':'none'))}" fill-rule="evenodd" stroke-linejoin="${esc(o.lineJoin||'round')}" stroke-linecap="${esc(o.lineCap||'round')}"${o.dash?` stroke-dasharray="${o.dash}"`:''}`;
if(o.type==='path'){const d=pathD(evaluatedPath(o));if(o.regionIds?.length){const rs=objects.filter(r=>r.panelOf===o.id&&r.semanticType==='region'&&!r.hidden);if(o.panelCuts?.length)style=style.replace(/fill="[^"]*"/,`fill="${rs.length&&rs.every(r=>r.fill&&r.fill!=='none'&&(r.opacity??1)===1)?esc(rs[0].fill):'none'}"`);panels=rs.map(r=>`<path data-region="${esc(r.id)}" d="${pathD(worldPath(r))}" fill="${esc(r.gradient?'url(#gradient-'+r.id+')':r.fill||'none')}" fill-rule="evenodd" opacity="${r.opacity??1}" stroke="none"/>${r.fabricTexture?.enabled!==false&&r.fabricTexture?`<path data-fabric-owner="${esc(r.id)}" d="${pathD(worldPath(r))}" fill="url(#fabric-${esc(r.id)})" fill-rule="evenodd"/>`:""}`).join('')+`<g transform="${mat(m)}"><path d="${d}" stroke="${esc(o.stroke||'none')}" stroke-width="${o.width??0}" fill="none" stroke-linejoin="round"/></g>`;}if(o.construction)m=I();visual=o.construction?partsSvg(effectParts(o.construction,o)):`<path d="${d}" ${style}/>`;if(o.fabricTexture&&o.fabricTexture.enabled!==false&&!o.panelCuts?.length)baseTexture+=`<path data-fabric-owner="${esc(o.id)}" d="${pathD(worldPath(o))}" fill="url(#fabric-${esc(o.id)})" fill-rule="evenodd" stroke="none"/>`;extra+=partsSvg(modifierParts(o));if(hit)visual+=`<path class="hit" d="${d}" fill="${o.closed?'transparent':'none'}" fill-rule="evenodd" stroke="transparent" stroke-width="10" vector-effect="non-scaling-stroke"/>`;}
else if(o.type==='text'){const size=o.fontSize??28,lines=String(o.text??'').split(/\r?\n/);visual=`<text x="0" y="${size}" ${style} font-family="Arial,sans-serif" font-size="${size}" xml:space="preserve">${lines.length===1?esc(lines[0]):lines.map((line,i)=>`<tspan x="0" dy="${i?size*1.3:0}">${esc(line)}</tspan>`).join('')}</text>`;if(hit)visual+=`<rect class="hit" width="${o.w}" height="${o.h}" fill="transparent"/>`;}
else if(o.type==='image')visual=`<image width="${o.w}" height="${o.h}" href="${esc(o.src)}" preserveAspectRatio="none"/>`;
else {const s=objects.find(x=>x.id===o.source);if(!s)return '';m=I();visual=partsSvg(effectParts(o,s));if(hit)visual+=`<path class="hit" d="${pathD(worldPath(s))}" fill="none" stroke="transparent" stroke-width="${o.type==='zipper'?Math.max(14,o.zipWidth+8):12}" vector-effect="non-scaling-stroke"/>`;}
const clip=o.clip?` clip-path="url(#clip-${esc(o.clip)})"`:'';return `<g data-id="${esc(o.id)}" opacity="${o.opacity??1}"${clip}${o.blendMode&&o.blendMode!=='normal'?` style="mix-blend-mode:${esc(o.blendMode)}"`:""}><g transform="${mat(m)}">${visual}</g>${baseTexture}${panels}${extra}</g>`;}
export function definitions(objects){return `<defs>${objects.map(o=>gradientDefinition(o,esc)).join('')}${objects.map(fabricPattern).join('')}${objects.filter(o=>o.type==='path'&&o.closed).map(o=>`<clipPath id="clip-${esc(o.id)}" clipPathUnits="userSpaceOnUse"><path d="${pathD(evaluatedPath(o))}" fill-rule="evenodd" clip-rule="evenodd" transform="${mat(o.matrix)}"/></clipPath>`).join('')}</defs>`;}
export function exportSvg(project,view,background='transparent'){const objects=project.views[view],d=project.document||documentSpec({width:700,height:700,ppi:96}),bg=background==='document'?documentBackground(project):background==='white'?'white':background==='transparent'?'none':background;const physical=d.unit==='px'?[''+d.widthPx,''+d.heightPx]:[d.width+d.unit,d.height+d.unit];return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${physical[0]}" height="${physical[1]}" viewBox="0 0 ${d.widthPx} ${d.heightPx}"><title>${esc(project.name)} · ${view}</title>${definitions(objects)}${bg!=='none'?`<rect width="${d.widthPx}" height="${d.heightPx}" fill="${esc(bg)}"/>`:''}${orderedObjects(project,view).filter(o=>visible(project,view,o)).map(o=>objectSvg(o,objects)).join('')}</svg>`;}
